        if arg.is_empty() {
            result.push(arg.to_string());
        } else {
            let fallback = Path::new(arg);
            let mut reconstructed = PathBuf::new();
            for component in nu_path::components(fallback) {
                match component {
                    Component::Normal(part) => {
                        if part.is_empty() {
                            reconstructed.push("");
                        } else {
                            reconstructed.push(part);
                        }
                    }
                    other => {
                        reconstructed.push(other);
                    }
                }
            }
            if reconstructed.as_os_str() == fallback.as_os_str() {
                result.push(reconstructed.to_string_lossy().into_owned());
            } else {
                result.push(arg.to_string());
            }
